// staleLandingPathClaims are the retired scalar-base and sole-landing-path claims. The
// path-scoped commit claim has one spelling for each form of its inner code span.
var staleLandingPathClaims = []string{
	"benchbase",
	"sole landing path",
	"path-scoped bench commit is the only",
	"path-scoped `bench commit` is the only",
	"path-scoped <code>bench commit</code> is the only",
	"branch's recorded pre-shift base",
}

// staleLandingPathAnchors forbids each stale claim in each file, with case folded.
func staleLandingPathAnchors() []Anchor {
	var rows []Anchor
	for _, file := range staleLandingPathFiles {
		for _, claim := range staleLandingPathClaims {
			rows = append(rows, Anchor{Group: AfterImplementSpec, File: file, Kind: ForbidCaseFoldedEmphasis, Needle: claim, Diagnostic: fmt.Sprintf("%s retains stale scalar or sole-path workflow claim %q", file, claim)})
		}
	}
	return rows
}

